import { mkdir, writeFile, cp, chmod } from 'node:fs/promises';
import { join } from 'node:path';

export function launcher({ vendor, url, sha256 }) {
  if (!['claude-code', 'codex'].includes(vendor) || !/^[a-f0-9]{64}$/.test(sha256) ||
      !/^https:\/\/github\.com\/alex-voloshin-dev\/kommutator\/releases\/download\/v[0-9]+\.[0-9]+\.[0-9]+\/kommutator-v[0-9]+\.[0-9]+\.[0-9]+-linux-x64\.tar\.gz$/.test(url)) throw new Error('Invalid hosted release identity');
  return `#!/bin/sh
# Generated by scripts/package-client-release.mjs. Download only on the MCP/manage path.
set -eu
umask 077
vendor='${vendor}'
expected='${sha256}'
url='${url}'
mode=\${1:-mcp}
[ "$#" -eq 0 ] || shift
fail() { printf 'kommutator: %s\\n' "$*" >&2; exit 1; }
home=\${KOM_HOME:-"$HOME/.kommutator"}
case "$home" in /*) ;; *) [ "$mode" != hook ] || exit 0; fail 'Private state path must be absolute.' ;; esac
cache="$home/downloads"
target="$cache/$expected"
bundle="$target/bundle"
if [ "$mode" = hook ]; then
  # Do not create files, acquire locks, download, unpack, or print on the hook path.
  [ ! -L "$home" ] && [ ! -L "$cache" ] && [ ! -L "$target" ] && [ ! -L "$bundle" ] || exit 0
  [ -f "$target/ready" ] && [ -x "$bundle/plugins/$vendor/bin/hook" ] || exit 0
  owner=$(id -u)
  for directory in "$home" "$cache" "$target"; do
    [ "$(stat -c '%u:%a' -- "$directory" 2>/dev/null)" = "$owner:700" ] || exit 0
  done
  exec "$bundle/plugins/$vendor/bin/hook" "$@" 2>/dev/null
  exit 0
fi
case "$mode" in mcp|manage) ;; *) fail 'Unknown launcher mode.' ;; esac
[ "$(uname -s)" = Linux ] && [ "$(uname -m)" = x86_64 ] || fail 'This preview supports Linux x64 / WSL2 Ubuntu x64 only.'
for command in curl sha256sum tar gzip flock stat mktemp realpath; do
  command -v "$command" >/dev/null 2>&1 || fail "Install $command first (Ubuntu: curl coreutils tar util-linux)."
done
owner=$(id -u)
private_dir() {
  [ ! -L "$1" ] || fail 'Private cache must not be a symbolic link.'
  mkdir -p -- "$1"
  [ "$(stat -c %u -- "$1")" = "$owner" ] || fail 'Private cache belongs to another user.'
  [ "$(realpath -- "$1")" = "$1" ] || fail 'Private cache path must be canonical without symbolic links.'
  chmod 700 -- "$1"
}
private_dir "$home"
private_dir "$cache"
[ ! -L "$cache/$expected.lock" ] || fail 'Unsafe cache lock.'
if [ -e "$cache/$expected.lock" ]; then
  [ -f "$cache/$expected.lock" ] && [ "$(stat -c %u -- "$cache/$expected.lock")" = "$owner" ] || fail 'Unsafe cache lock.'
fi
exec 9>"$cache/$expected.lock"
flock -w 180 9 || fail 'Another client download is still running. Retry MCP connection.'
[ ! -L "$target" ] || fail 'Unsafe cached release.'
if [ ! -f "$target/ready" ]; then
  [ ! -e "$target" ] || fail 'Incomplete cached release; remove that release directory and retry.'
  stage=$(mktemp -d "$cache/.download.XXXXXXXX")
  trap 'rm -rf -- "$stage"' EXIT
  trap 'exit 1' HUP INT TERM
  printf 'kommutator: downloading verified Linux x64 client once...\\n' >&2
  curl --fail --silent --show-error --location --proto '=https' --proto-redir '=https' --connect-timeout 15 --max-time 150 --max-filesize 268435456 --output "$stage/client.tar.gz" "$url" || fail 'Client download failed. Check internet access and reconnect the MCP server.'
  printf '%s  %s\\n' "$expected" "$stage/client.tar.gz" | sha256sum -c - >/dev/null || fail 'Client checksum mismatch; nothing was installed.'
  mkdir "$stage/bundle"
  tar --extract --gzip --file "$stage/client.tar.gz" --directory "$stage/bundle" --no-same-owner --no-same-permissions || fail 'Client archive extraction failed.'
  [ -x "$stage/bundle/plugins/$vendor/bin/mcp" ] && [ -x "$stage/bundle/plugins/$vendor/runtime/payload/node" ] || fail 'Client archive is incomplete.'
  rm -- "$stage/client.tar.gz"
  printf '%s\\n' "$expected" > "$stage/ready"
  mv -- "$stage" "$target"
  trap - EXIT HUP INT TERM
fi
[ ! -L "$target/ready" ] && [ ! -L "$bundle" ] && [ "$(cat "$target/ready")" = "$expected" ] || fail 'Invalid cached release.'
[ "$(stat -c %u -- "$target")" = "$owner" ] && [ "$(stat -c %a -- "$target")" = 700 ] || fail 'Unsafe cached release permissions.'
flock -u 9
exec 9>&-
if [ "$mode" = manage ]; then exec "$bundle/plugins/$vendor/bin/manage" "$@"; fi
exec "$bundle/plugins/$vendor/bin/mcp" "$@"
`;
}

export async function writeHostedPlugins(root, release, claudeArchive) {
  const events = ['SessionStart', 'UserPromptSubmit', 'PostToolUse', 'Stop', 'SessionEnd'];
  for (const vendor of ['codex']) {
    const dest = join(root, 'plugins/hosted', vendor);
    await mkdir(join(dest, 'bin'), { recursive: true });
    await writeFile(join(dest, 'bin/launch'), launcher({ vendor, ...release }));
    await chmod(join(dest, 'bin/launch'), 0o755);
    await cp(join(root, 'LICENSE'), join(dest, 'LICENSE'));
    await cp(join(root, 'plugins/claude-code/skills'), join(dest, 'skills'), { recursive: true });
    const variable = vendor === 'claude-code' ? '${CLAUDE_PLUGIN_ROOT}' : '${PLUGIN_ROOT}';
    const mcp = vendor === 'codex'
      ? { command: './bin/launch', args: ['mcp'], cwd: './', startup_timeout_sec: 180 }
      : { command: variable + '/bin/launch', args: ['mcp'] };
    await writeFile(join(dest, '.mcp.json'), JSON.stringify({ mcpServers: { kommutator: mcp } }, null, 2) + '\n');
    await mkdir(join(dest, 'hooks'), { recursive: true });
    const hooks = Object.fromEntries(events.map(event => [event, [{ hooks: [{ type: 'command', command: `exec "${variable}/bin/launch" hook ${event}`, timeout: 1 }] }]]));
    await writeFile(join(dest, 'hooks/hooks.json'), JSON.stringify({ hooks }, null, 2) + '\n');
    const directory = vendor === 'codex' ? '.codex-plugin' : '.claude-plugin';
    await mkdir(join(dest, directory), { recursive: true });
    const manifest = { name: 'kommutator', version: release.version, description: 'Connect coding agents to your hub. First startup downloads a checksum-pinned Linux x64 client; setup_start opens the private connection form.', mcpServers: './.mcp.json', ...(vendor === 'codex' ? { hooks: './hooks/hooks.json' } : {}) };
    await writeFile(join(dest, directory, 'plugin.json'), JSON.stringify(manifest, null, 2) + '\n');
    await writeFile(join(dest, 'release.json'), JSON.stringify(release, null, 2) + '\n');
  }
  await mkdir(join(root, '.claude-plugin'), { recursive: true });
  await writeFile(join(root, '.claude-plugin/marketplace.json'), JSON.stringify({ name: 'kommutator', owner: { name: 'alex-voloshin-dev' }, plugins: [{ name: 'kommutator', source: { source: 'archive', ...claudeArchive }, version: release.version }] }, null, 2) + '\n');
  await mkdir(join(root, '.agents/plugins'), { recursive: true });
  await writeFile(join(root, '.agents/plugins/marketplace.json'), JSON.stringify({ name: 'kommutator', plugins: [{ name: 'kommutator', source: { source: 'local', path: './plugins/hosted/codex' } }] }, null, 2) + '\n');
}
